BandParams off() { return BandParams {}; }

BandParams on (int src, int groupEnd, int sync, Wave wave, bool invert, float time, float lcf, float hcf,
               float fb, float tap, float speed, float depth, float pan, float level)
{
    BandParams b;
    b.on = true; b.source = src; b.groupEnd = groupEnd; b.sync = sync; b.wave = wave; b.invert = invert;
    b.timeMs = time; b.lowCut = lcf; b.highCut = hcf; b.feedback = fb; b.tapPercent = tap;
    b.speed = speed; b.depth = depth; b.pan = pan; b.level = level;
    return b;
}

FactoryPreset make (const char* name, float effect, float direct, float directPan, std::array<BandParams, kNumBands> bands)
{
    FactoryPreset p { name, {} };
    p.params.band = bands;
    p.params.global.effectLevel = effect;
    p.params.global.directLevel = direct;
    p.params.global.directPan = directPan;
    return p;
}
